import Foundation

/// The models the app can download: for each, where it comes from (a pinned revision), and every file's size and SHA-256.
/// Generated by scripts/make-manifest.py from known-good copies and shipped inside the app as models-manifest.json.
public struct ModelManifest: Codable, Equatable, Sendable {
    public struct File: Codable, Equatable, Sendable {
        /// Path inside the model's folder, always relative and never containing "..".
        public let path: String
        public let sha256: String
        public let size: Int64
        public init(path: String, sha256: String, size: Int64) { self.path = path; self.sha256 = sha256; self.size = size }
    }

    public struct Model: Codable, Equatable, Sendable {
        /// "speech" or "cleanup".
        public let id: String
        public let name: String
        /// Hugging Face repository, "owner/name", and the exact revision (a 40-character commit id) the files are taken from.
        public let repo: String
        public let revision: String
        public let licence: String
        /// Folder under the models folder, for example "cleanup/Qwen3-4B-Instruct-2507-4bit".
        public let destination: String
        public let files: [File]
        public init(id: String, name: String, repo: String, revision: String, licence: String, destination: String, files: [File]) {
            self.id = id; self.name = name; self.repo = repo; self.revision = revision; self.licence = licence; self.destination = destination; self.files = files
        }

        public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

        /// Where one file comes from: the repository at the pinned revision.
        public func url(for file: File) -> URL {
            var allowed = CharacterSet.urlPathAllowed; allowed.remove(charactersIn: "?#")
            let path = file.path.split(separator: "/").map { String($0).addingPercentEncoding(withAllowedCharacters: allowed) ?? String($0) }.joined(separator: "/")
            return URL(string: "https://huggingface.co/\(repo)/resolve/\(revision)/\(path)")!
        }
    }

    public let models: [Model]
    public init(models: [Model]) { self.models = models }

    public func model(_ id: String) -> Model? { models.first { $0.id == id } }

    public enum ManifestError: Error, Equatable, CustomStringConvertible {
        case unreadable(String)
        case invalid(String)
        public var description: String {
            switch self { case .unreadable(let m): return "the model list can't be read: \(m)"; case .invalid(let m): return "the model list is not valid: \(m)" }
        }
    }

    public static func load(from url: URL) throws -> ModelManifest {
        let data: Data
        do { data = try Data(contentsOf: url) } catch { throw ManifestError.unreadable("\(error.localizedDescription)") }
        do {
            let manifest = try JSONDecoder().decode(ModelManifest.self, from: data)
            try manifest.validate()
            return manifest
        } catch let e as ManifestError { throw e } catch { throw ManifestError.invalid("\(error)") }
    }

    /// The manifest inside the running app.
    public static func bundled() throws -> ModelManifest {
        guard let url = Bundle.main.url(forResource: "models-manifest", withExtension: "json") else { throw ManifestError.unreadable("it is missing from the app") }
        return try load(from: url)
    }

    /// Everything the downloader relies on: safe paths, well-formed checksums, pinned revisions, allowed hosts.
    public func validate() throws {
        guard !models.isEmpty else { throw ManifestError.invalid("it lists no models") }
        var ids = Set<String>()
        for m in models {
            guard ids.insert(m.id).inserted else { throw ManifestError.invalid("model \"\(m.id)\" is listed twice") }
            guard Self.isSafeRelativePath(m.destination) else { throw ManifestError.invalid("\(m.id): unsafe folder \"\(m.destination)\"") }
            guard m.repo.range(of: #"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"#, options: .regularExpression) != nil else { throw ManifestError.invalid("\(m.id): bad repository name") }
            guard m.revision.range(of: #"^[0-9a-f]{40}$"#, options: .regularExpression) != nil else { throw ManifestError.invalid("\(m.id): the revision must be a full commit id") }
            guard !m.files.isEmpty else { throw ManifestError.invalid("\(m.id): no files") }
            var paths = Set<String>()
            for f in m.files {
                guard Self.isSafeRelativePath(f.path) else { throw ManifestError.invalid("\(m.id): unsafe file path \"\(f.path)\"") }
                guard paths.insert(f.path).inserted else { throw ManifestError.invalid("\(m.id): \(f.path) is listed twice") }
                guard f.sha256.range(of: #"^[0-9a-f]{64}$"#, options: .regularExpression) != nil else { throw ManifestError.invalid("\(m.id): bad checksum for \(f.path)") }
                guard f.size > 0 else { throw ManifestError.invalid("\(m.id): \(f.path) has no size") }
                guard DownloadPolicy.isAllowed(m.url(for: f)) else { throw ManifestError.invalid("\(m.id): \(f.path) is not on an allowed host") }
            }
        }
    }

    /// Relative, no empty or "." or ".." parts, no backslashes or colons: nothing that could point outside the models folder.
    static func isSafeRelativePath(_ path: String) -> Bool {
        guard !path.isEmpty, !path.hasPrefix("/"), !path.contains("\\"), !path.contains(":") else { return false }
        return path.split(separator: "/", omittingEmptySubsequences: false).allSatisfy { !$0.isEmpty && $0 != "." && $0 != ".." }
    }
}

/// Which addresses the downloader may talk to: Hugging Face over https, and the content hosts it redirects to.
public enum DownloadPolicy {
    public static func isAllowed(_ url: URL) -> Bool {
        guard url.scheme == "https", let host = url.host?.lowercased(), url.user == nil, url.password == nil else { return false }
        return ["huggingface.co", "hf.co"].contains(host) || host.hasSuffix(".huggingface.co") || host.hasSuffix(".hf.co")
    }
}
